from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f'{path}: expected one replacement site, found {count}')
    file.write_text(text.replace(old, new, 1))


dots = Path('packages/game-core/src/combat/combat-dots.ts')
dots.write_text("""import type { CombatEffectRecipient, CombatEncounterIssue, CombatEncounterState } from './actions'\nimport { normalizeCombatEffectState, type CombatPoisonInstance } from './combat-effect-state'\n\nexport const CURRENT_POISON_PROFILE_VERSION = 1 as const\nexport const CURRENT_POISON_DAMAGE = 2 as const\n\nexport interface CurrentPoisonEffect {\n  type: 'poison'\n  recipient: CombatEffectRecipient\n}\n\nexport function currentPoisonInstance(\n  state: CombatEncounterState,\n  targetCombatantId: string,\n): CombatPoisonInstance | null {\n  return (\n    normalizeCombatEffectState(state.effectState).poison.find(\n      (instance) => instance.targetCombatantId === targetCombatantId,\n    ) ?? null\n  )\n}\n\nexport function hasCurrentPoison(\n  state: CombatEncounterState,\n  targetCombatantId: string,\n): boolean {\n  return currentPoisonInstance(state, targetCombatantId) !== null\n}\n\nexport function currentPoisonEndTurnDamage(\n  state: CombatEncounterState,\n  targetCombatantId: string,\n): number {\n  return hasCurrentPoison(state, targetCombatantId) ? CURRENT_POISON_DAMAGE : 0\n}\n\nexport function applyCurrentPoisonState(\n  state: CombatEncounterState,\n  sourceCombatantId: string,\n  targetCombatantId: string,\n  sourceActionId: string,\n): CombatEncounterState {\n  const effectState = normalizeCombatEffectState(state.effectState)\n  const existing = effectState.poison.find(\n    (instance) => instance.targetCombatantId === targetCombatantId,\n  )\n  const instance = {\n    targetCombatantId,\n    sourceCombatantId,\n    sourceActionId,\n    profileVersion: CURRENT_POISON_PROFILE_VERSION,\n    movementRemainder: existing?.movementRemainder ?? 0,\n  }\n\n  return {\n    ...state,\n    effectState: {\n      ...effectState,\n      poison: [\n        ...effectState.poison.filter(\n          (candidate) => candidate.targetCombatantId !== targetCombatantId,\n        ),\n        instance,\n      ].sort((left, right) => left.targetCombatantId.localeCompare(right.targetCombatantId)),\n    },\n  }\n}\n\nexport function removeCurrentPoisonState(\n  state: CombatEncounterState,\n  targetCombatantId: string,\n): CombatEncounterState {\n  const effectState = normalizeCombatEffectState(state.effectState)\n  return {\n    ...state,\n    effectState: {\n      ...effectState,\n      poison: effectState.poison.filter(\n        (instance) => instance.targetCombatantId !== targetCombatantId,\n      ),\n    },\n  }\n}\n\nexport function validateCombatDotState(\n  state: CombatEncounterState,\n): readonly CombatEncounterIssue[] {\n  if (!state.effectState) return []\n\n  const poison = state.effectState.poison\n  if (!Array.isArray(poison)) {\n    return [{ field: 'effectState.poison', message: 'Poison state must be an array.' }]\n  }\n\n  const combatantIds = new Set(state.tactical.battle.combatants.map((row) => row.id))\n  const targetIds = new Set<string>()\n  let invalid = false\n  let previousTargetId: string | null = null\n\n  for (const instance of poison) {\n    if (\n      !combatantIds.has(instance.targetCombatantId) ||\n      !combatantIds.has(instance.sourceCombatantId) ||\n      typeof instance.sourceActionId !== 'string' ||\n      instance.sourceActionId.length === 0 ||\n      instance.sourceActionId.trim() !== instance.sourceActionId ||\n      instance.profileVersion !== CURRENT_POISON_PROFILE_VERSION ||\n      !Number.isSafeInteger(instance.movementRemainder) ||\n      instance.movementRemainder < 0 ||\n      instance.movementRemainder > 4 ||\n      targetIds.has(instance.targetCombatantId) ||\n      (previousTargetId !== null && previousTargetId > instance.targetCombatantId)\n    ) {\n      invalid = true\n    }\n    targetIds.add(instance.targetCombatantId)\n    previousTargetId = instance.targetCombatantId\n  }\n\n  return invalid\n    ? [\n        {\n          field: 'effectState.poison',\n          message:\n            'Poison state must contain one valid current-profile instance per target, sorted by target ID, with movement progress from 0 to 4.',\n        },\n      ]\n    : []\n}\n""")

actions = 'packages/game-core/src/combat/actions.ts'
replace_once(
    actions,
    "import { applyCurrentPoisonState } from './combat-dots'",
    """import {\n  CURRENT_POISON_DAMAGE,\n  applyCurrentPoisonState,\n  currentPoisonEndTurnDamage,\n  currentPoisonInstance,\n  hasCurrentPoison,\n  removeCurrentPoisonState,\n  validateCombatDotState,\n} from './combat-dots'""",
)
replace_once(
    actions,
    """  const outgoingHpAfterTicks = getStatusRow(state, outgoingId).statuses.reduce((hp, status) => {\n    const periodic = getStatusDefinition(content, status.statusId, status.statusVersion).endOfTurn\n    if (!periodic || hp <= 0) return hp\n    const amount = periodic.amount * status.stacks\n    return periodic.type === 'damage'\n      ? Math.max(0, hp - amount)\n      : Math.min(outgoing.maxHp, hp + incomingHealingAmount(state, outgoingId, amount, content))\n  }, outgoing.hp)""",
    """  const legacyOutgoingHpAfterTicks = getStatusRow(state, outgoingId).statuses.reduce(\n    (hp, status) => {\n      const periodic = getStatusDefinition(content, status.statusId, status.statusVersion).endOfTurn\n      if (!periodic || hp <= 0) return hp\n      const amount = periodic.amount * status.stacks\n      return periodic.type === 'damage'\n        ? Math.max(0, hp - amount)\n        : Math.min(\n            outgoing.maxHp,\n            hp + incomingHealingAmount(state, outgoingId, amount, content),\n          )\n    },\n    outgoing.hp,\n  )\n  const outgoingHpAfterTicks = Math.max(\n    0,\n    legacyOutgoingHpAfterTicks - currentPoisonEndTurnDamage(state, outgoingId),\n  )""",
)
replace_once(
    actions,
    """  const periodic = resolveEndOfTurnStatuses(nextState, outgoingId, content)\n  nextState = periodic.state\n  events.push(...periodic.events)\n  const recovery = resolveEndOfTurnRecovery(nextState, outgoingId, content)""",
    """  const periodic = resolveEndOfTurnStatuses(nextState, outgoingId, content)\n  nextState = periodic.state\n  events.push(...periodic.events)\n  const currentDots = resolveCurrentEndOfTurnDots(nextState, outgoingId, content)\n  nextState = currentDots.state\n  events.push(...currentDots.events)\n  const recovery = resolveEndOfTurnRecovery(nextState, outgoingId, content)""",
)
replace_once(
    actions,
    """  const issues: CombatEncounterIssue[] = [\n    ...validateTerrainOverlays(state),\n    ...validateOngoingRecoveryState(state),\n  ]""",
    """  const issues: CombatEncounterIssue[] = [\n    ...validateTerrainOverlays(state),\n    ...validateOngoingRecoveryState(state),\n    ...validateCombatDotState(state),\n  ]""",
)
replace_once(
    actions,
    """      } else if (effect.type === 'remove-status') {\n        beforeValue =\n          getStatusRow(before, recipientId)\n            .statuses.filter((status) => effect.statusIds.includes(status.statusId))\n            .map((status) => status.statusId)\n            .join(',') || 'none'\n        afterValue = 'none'""",
    """      } else if (effect.type === 'remove-status') {\n        const removedStatusIds = getStatusRow(before, recipientId)\n          .statuses.filter((status) => effect.statusIds.includes(status.statusId))\n          .map((status) => status.statusId)\n        if (effect.statusIds.includes('poison') && hasCurrentPoison(before, recipientId)) {\n          removedStatusIds.push('poison')\n        }\n        beforeValue = [...new Set(removedStatusIds)].sort(compareStableString).join(',') || 'none'\n        afterValue = 'none'""",
)
replace_once(
    actions,
    """  if (effect.type === 'remove-status') {\n    return {\n      state: removeStatuses(state, recipientId, effect.statusIds),\n      events: getStatusRow(state, recipientId)\n        .statuses.filter((status) => effect.statusIds.includes(status.statusId))\n        .map((status) => ({\n          event: 'status_removed' as const,\n          actionId,\n          sourceCombatantId: actorId,\n          targetCombatantId: recipientId,\n          statusId: status.statusId,\n        })),\n    }\n  }""",
    """  if (effect.type === 'remove-status') {\n    const removedStatusIds = getStatusRow(state, recipientId)\n      .statuses.filter((status) => effect.statusIds.includes(status.statusId))\n      .map((status) => status.statusId)\n    const removesCurrentPoison =\n      effect.statusIds.includes('poison') && hasCurrentPoison(state, recipientId)\n    if (removesCurrentPoison) removedStatusIds.push('poison')\n\n    let nextState = removeStatuses(state, recipientId, effect.statusIds)\n    if (removesCurrentPoison) nextState = removeCurrentPoisonState(nextState, recipientId)\n\n    return {\n      state: nextState,\n      events: [...new Set(removedStatusIds)].sort(compareStableString).map((statusId) => ({\n        event: 'status_removed' as const,\n        actionId,\n        sourceCombatantId: actorId,\n        targetCombatantId: recipientId,\n        statusId,\n      })),\n    }\n  }""",
)
replace_once(
    actions,
    """  return { state: nextState, events }\n}\n\nfunction completeBattleIfResolved(state: CombatEncounterState): CombatResolutionTransition {""",
    """  return { state: nextState, events }\n}\n\nfunction resolveCurrentEndOfTurnDots(\n  state: CombatEncounterState,\n  combatantId: string,\n  content: CombatContentCatalog,\n): CombatResolutionTransition {\n  const poison = currentPoisonInstance(state, combatantId)\n  const target = getCombatant(state.tactical.battle, combatantId)\n  if (!poison || target.hp <= 0) return { state, events: [] }\n\n  const hpAfter = Math.max(0, target.hp - CURRENT_POISON_DAMAGE)\n  let nextState = withUpdatedCombatant(state, combatantId, { ...target, hp: hpAfter })\n  const events: CombatResolutionEvent[] = [\n    {\n      event: 'damage_applied',\n      actionId: 'status.poison.current.v1',\n      sourceCombatantId: poison.sourceCombatantId,\n      targetCombatantId: combatantId,\n      amount: target.hp - hpAfter,\n      hpBefore: target.hp,\n      hpAfter,\n    },\n  ]\n\n  if (hpAfter < target.hp) {\n    const revealed = removeGameplayTags(\n      nextState,\n      poison.sourceCombatantId,\n      combatantId,\n      'status.poison.current.v1',\n      ['Invisible'],\n      content,\n    )\n    nextState = revealed.state\n    events.push(...revealed.events)\n  }\n\n  return { state: nextState, events }\n}\n\nfunction completeBattleIfResolved(state: CombatEncounterState): CombatResolutionTransition {""",
)

print('Applied persistent current-Poison end-turn, removal, and validation runtime.')
